   [11]={next_id=12, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“……黄金的纪元于此开始，墨尔欧放下兵戈，执起律法与麦穗的双杖，在曾浸透鲜血的土壤之上建起赤色的城墙。”", msg_color="", msg_size=0, talker="仪仗兵", audio="", img="arts/ui/bg/story/storybg_103.jpg", video_url="", music_id="71", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [12]={next_id=13, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="年轻的仪仗兵身着华服，安静地坐在空无一人的书架旁诵读受众的诗歌。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [13]={next_id=14, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“工匠们以宝石镶嵌石像的眼睛，诗人们将光明与公正编纂成典。”", msg_color="", msg_size=0, talker="仪仗兵", audio="", img="arts/ui/bg/story/storybg_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
