   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="话音未落，希尔妲当即掀翻了桌子，将桌子朝着聆风砸过去，然后抽身向着窗户逃窜。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但还没跑几步，无形的镣铐就将她的四肢锁住，紧接着狂涌的风将她整个人拉了回来，狠狠地拍在了书架上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="锁住希尔妲的风散去，她从书架上掉了下来，有些踉跄地落在地上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="都说了，别紧张，希尔妲。", msg_color="", msg_size=0, talker="聆风", audio="", img="arts/ui/bg/story/storybg_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4525", 0, 0, 109.5, 191.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
